function stripHtml(s){ return String(s||'').replace(/<[^>]*>/g,' ').replace(/&[a-z#0-9]+;/gi,' ').replace(/\s+/g,' ').trim(); }
function toMs(v){
  if(v===null||v===undefined||v==='') return 0;
  if(typeof v==='number') return v<1e12 ? v*1000 : v;           // unix seconds vs ms
  var s=String(v).trim();
  if(/^\d+$/.test(s)){ var n=parseInt(s,10); return n<1e12 ? n*1000 : n; }
  var t=Date.parse(s.replace(' ','T'));                          // ISO or "YYYY-MM-DD HH:MM:SS"
  return isNaN(t)?0:t;
}
function norm(source,id,title,company,url,location,tags,desc,date){
  const t = stripHtml(title);
  const d = stripHtml(desc).slice(0,600);
  const tagArr = Array.isArray(tags) ? tags.map(x=>String(x)) : [];
  return {
    source, id: String(id || url || t),
    title: t,
    company: (String(company||'').trim()) || '—',
    url: String(url||'').trim(),
    location: (String(location||'').trim()) || 'Remote',
    tags: tagArr,
    date: date || '',
    ts: toMs(date),
    match_text: (t + ' ' + tagArr.join(' ') + ' ' + d).toLowerCase()
  };
}

