// OnlineJobs.ph — scrape public job search HTML (best-effort; may break if OLJ redesigns).
const KEYWORDS = ['web developer', 'ui ux designer', 'graphic designer', 'automation'];
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Safari/537.36';
const out = [];
for (const kw of KEYWORDS) {
  try {
    const resp = await this.helpers.httpRequest({
      url: 'https://www.onlinejobs.ph/jobseekers/jobsearch?jobkeyword=' + encodeURIComponent(kw),
      headers: { 'User-Agent': UA }, timeout: 25000
    });
    const body = (typeof resp === 'string') ? resp : JSON.stringify(resp);
    const cards = body.split('<!-- Start -->');
    for (const card of cards) {
      const hrefM = card.match(/href="(\/jobseekers\/job\/[^"]+)"/);
      if (!hrefM) continue;
      const href = hrefM[1];
      const idM = href.match(/(\d+)\s*$/);
      const id = idM ? idM[1] : href;
      const h4M = card.match(/<h4[^>]*>([\s\S]*?)<\/h4>/);
      let title = '';
      if (h4M) title = stripHtml(h4M[1].replace(/<span[^>]*class="badge[^"]*"[^>]*>[\s\S]*?<\/span>/gi, '')).trim();
      if (!title) continue;
      const salM = card.match(/<dd class="col">\s*([^<]*?)\s*<\/dd>/);
      const salary = salM ? salM[1].trim() : '';
      const dateM = card.match(/data-temp="([^"]+)"/);
      const descM = card.match(/<div class="desc[^"]*">([\s\S]*?)<\/div>/);
      const tags = []; const tagRe = /class=['"]badge['"][^>]*>([^<]+)</g; let tm;
      while ((tm = tagRe.exec(card)) !== null) tags.push(tm[1].trim());
      out.push(norm('OnlineJobs.ph', id, title, salary || 'OnlineJobs.ph', 'https://www.onlinejobs.ph' + href, 'Philippines / Remote', tags, descM ? descM[1] : '', dateM ? dateM[1] : ''));
    }
  } catch (e) { /* skip this keyword */ }
}
return out.map(json => ({ json }));

