  const data = (it.json && Array.isArray(it.json.data)) ? it.json.data : [];
  for (const j of data) {
    const tags = [j.job_employment_type, j.job_publisher].filter(Boolean);
    out.push(norm(
      'JSearch:' + (j.job_publisher || '?'),
      j.job_id, j.job_title, j.employer_name,
      j.job_apply_link || j.job_google_link,
      j.job_city || j.job_country || (j.job_is_remote ? 'Remote' : ''),
      tags, j.job_description, j.job_posted_at_datetime_utc
    ));
  }
