return out.map(json => ({ json }));

const SKILLS = {
  'Web Dev (React/Next)': ['react','reactjs','react.js','next.js','nextjs','next js','javascript',' js ','typescript','frontend','front-end','front end','html','css','tailwind','web developer','web development','jamstack','vue','node.js','nodejs'],
  'UI/UX Design': ['ui/ux','ui ux','uiux','ui design','ux design','user interface','user experience','figma','product design','web design','wireframe','prototype','prototyping','design system'],
  'AI Automation': ['ai automation','automation','n8n','make.com','zapier','integromat','workflow automation','ai agent','ai agents','llm','chatbot','no-code','no code','nocode','rpa'],
  'Graphic Design': ['graphic design','graphic designer','photoshop','illustrator','adobe','canva','premiere','video editing','video editor','motion graphics','branding','visual design','after effects']
};
const all = $input.all().map(i => i.json).filter(j => j && j.url && j.title);
// dedup within this run
const byKey = {};
for (const j of all) {
  const k = (String(j.url || '').split('?')[0].toLowerCase()) || (String(j.title) + String(j.company)).toLowerCase();
  if (!byKey[k]) byKey[k] = j;
}
let jobs = Object.values(byKey);
const totalDeduped = jobs.length;
// recency filter — keep only jobs posted within the last maxAgeDays (undated jobs are kept as a safety net)
const maxAgeDays = Number(($('Config').first().json || {}).maxAgeDays) || 10;
const NOW = Date.now();
const cutoff = NOW - maxAgeDays * 86400000;
jobs = jobs.filter(j => !j.ts || j.ts >= cutoff);
const tooOld = totalDeduped - jobs.length;
// score against skills
function score(j) {
  const txt = ' ' + (j.match_text || '') + ' ';
  const matched = []; let hits = 0;
  for (const grp of Object.keys(SKILLS)) {
    let g = false;
    for (const kw of SKILLS[grp]) { if (txt.indexOf(kw) !== -1) { hits++; g = true; } }
    if (g) matched.push(grp);
  }
  return { hits, matched };
}
jobs = jobs.map(j => { const s = score(j); return Object.assign({}, j, { score: s.hits, matched_skills: s.matched, age_days: j.ts ? Math.floor((NOW - j.ts) / 86400000) : null }); })
           .filter(j => j.matched_skills.length > 0);
// cross-run dedup so the same job is never posted twice (persists on scheduled runs)
const store = $getWorkflowStaticData('global');
let seen = store.seenJobs || {};
const fresh = [];
for (const j of jobs) {
  const k = String(j.url || '').split('?')[0].toLowerCase();
  if (seen[k]) continue;
  fresh.push(j);
}
// newest first (undated jobs sink to the bottom); score breaks ties on same timestamp
fresh.sort((a, b) => ((b.ts || 0) - (a.ts || 0)) || (b.score - a.score));
const stamp = Date.now();
for (const j of fresh) { const k = String(j.url || '').split('?')[0].toLowerCase(); seen[k] = stamp; }
// prune memory to the newest 1500 keys
const entries = Object.keys(seen).map(k => [k, seen[k]]).sort((a, b) => b[1] - a[1]).slice(0, 1500);
seen = {}; for (const e of entries) seen[e[0]] = e[1];
store.seenJobs = seen;
return [{ json: { count: fresh.length, total_scanned: all.length, too_old_skipped: tooOld, max_age_days: maxAgeDays, jobs: fresh } }];

const d = $json;
const jobs = Array.isArray(d.jobs) ? d.jobs : [];
const show = jobs.slice(0, 30);
const lines = show.map((j, i) => {
  const skills = (j.matched_skills || []).join(', ');
  const age = (j.age_days === null || j.age_days === undefined) ? 'recent' : (j.age_days <= 0 ? 'today' : j.age_days + 'd ago');
  return (i + 1) + '. *<' + j.url + '|' + j.title + '>*\n' +
         '   ' + j.company + ' · _' + j.source + '_ · 📍 ' + j.location + ' · 🕐 ' + age + '\n' +
         '   🎯 ' + skills + '  (score ' + j.score + ')';
});
let text = ':briefcase: *' + d.count + ' new job match' + (d.count === 1 ? '' : 'es') + '* (posted in last ' + d.max_age_days + ' days)  ·  scanned ' + d.total_scanned + '\n\n' + lines.join('\n\n');
if (jobs.length > show.length) text += '\n\n…and ' + (jobs.length - show.length) + ' more matches not shown.';
return [{ json: { text } }];
